#include <map>
#include <iterator>
#include <iostream>

int main() {
    std::map<double, int> book;          // price -> resting size, ascending
    book[101.50] += 300;
    book[101.25] += 500;
    book[101.50] += 200;                 // same level: accumulates
    book[100.75] += 100;

    std::cout << "levels=" << book.size() << "\n";
    auto best = std::prev(book.end());   // highest price = best bid
    std::cout << "best=" << best->first << " size=" << best->second << "\n";
    best->second -= 350;                 // lift 350 at the top level
    std::cout << "best=" << best->first << " size=" << best->second << "\n";
}

#include <unordered_map>
#include <string>
#include <cstdint>
#include <functional>
#include <iostream>

struct Symbol {
    std::string venue;
    std::uint32_t id;
    bool operator==(const Symbol& o) const { return venue == o.venue && id == o.id; }
};

struct SymbolHash {
    std::size_t operator()(const Symbol& s) const {
        std::size_t h = std::hash<std::string>{}(s.venue);
        return h ^ (std::hash<std::uint32_t>{}(s.id) << 1);
    }
};

int main() {
    std::unordered_map<Symbol, double, SymbolHash> position;
    position[{"XEUR", 1177}] = 12.0;     // e.g. FGBM futures
    position[{"XEUR", 1177}] += 3.0;
    std::cout << position[{"XEUR", 1177}] << "\n";
}

